# Inhoud voor de cursussen fysica 5Wet (elektrostatica en gemengde schakelingen) in het nieuwe formaat.
# D(idee, vb, test, wb, letop, stappen, steun). vb = (titel, opgave, [(stap, uitleg met het waarom)]).
# wb = (start, tijdens, einde): lijsten van (vraag, antwoord[, typische fout]).
# Begrippen: de bestaande begrippenlijst van elke pagina wordt aangevuld met 'extra'.

def D(idee, vb, test, wb, letop=None, stappen=None, steun=None):
    return dict(idee=idee, vb=vb, test=test, wb=wb, letop=letop, stappen=stappen, steun=steun)

